/**
 * Tests for bundle-report.mjs
 * Run: node --test scripts/bundle-report.test.mjs
 *
 * Schema note: __bundle_analysis.json uses the schema generated by the
 * workflow's extract-bundle-sizes step (see bundle-analysis.yml), which
 * reads Next.js build output and computes per-route First Load JS bytes:
 *   { "/route": { "raw": <bytes>, "gzip": <bytes> }, ... }
 */

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { writeFileSync, mkdirSync, rmSync, existsSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SCRIPT = join(__dirname, 'bundle-report.mjs');

/** Helper: run the script and capture output */
function run(args, { expectFail = false } = {}) {
  try {
    const stdout = execFileSync(process.execPath, [SCRIPT, ...args], {
      encoding: 'utf8',
    });
    return { code: 0, stdout };
  } catch (err) {
    if (!expectFail) throw err;
    return { code: err.status ?? 1, stdout: err.stdout ?? '' };
  }
}

/** Helper: write a temp JSON file and return its path */
function writeTmp(dir, name, data) {
  const p = join(dir, name);
  writeFileSync(p, JSON.stringify(data));
  return p;
}

// Create a temp dir for test artifacts
const TMP = join(tmpdir(), `bundle-report-test-${process.pid}`);
mkdirSync(TMP, { recursive: true });

// Clean up after tests
process.on('exit', () => {
  try { rmSync(TMP, { recursive: true, force: true }); } catch {}
});

// ---------------------------------------------------------------------------
// Test 1: delta table with 🚨 marker for >5% growth
// ---------------------------------------------------------------------------
describe('bundle-report', () => {
  it('produces delta table with 🚨 for route with >5% growth', () => {
    const baseline = {
      '/dashboard': { raw: 100_000, gzip: 30_000 },
      '/persons': { raw: 50_000, gzip: 15_000 },
    };
    const current = {
      '/dashboard': { raw: 115_000, gzip: 34_500 }, // +15% → should get 🚨
      '/persons': { raw: 51_000, gzip: 15_300 },   // +2% → no 🚨
    };

    const baselinePath = writeTmp(TMP, 'baseline1.json', baseline);
    const currentPath = writeTmp(TMP, 'current1.json', current);
    const outputPath = join(TMP, 'report1.md');

    const { stdout } = run([
      '--current', currentPath,
      '--baseline', baselinePath,
      '--output', outputPath,
    ]);

    const md = readFileSync(outputPath, 'utf8');

    // Marker line must be present
    assert.ok(
      md.startsWith('<!-- ancstra-bundle-report -->'),
      'Report must start with the marker comment'
    );

    // 🚨 must appear for /dashboard (>5% growth)
    assert.ok(md.includes('🚨'), 'Markdown should contain 🚨 for >5% growth');
    assert.ok(md.includes('/dashboard'), 'Report should mention /dashboard');

    // /persons should NOT have 🚨
    const personsRow = md.split('\n').find(l => l.includes('/persons'));
    assert.ok(personsRow, '/persons row should exist');
    assert.ok(!personsRow.includes('🚨'), '/persons row must not have 🚨 (only 2% growth)');

    // stdout should also contain the markdown
    assert.ok(stdout.includes('<!-- ancstra-bundle-report -->'), 'stdout should contain marker');
  });

  // -------------------------------------------------------------------------
  // Test 2: missing baseline → exit 0 + "no baseline yet" message
  // -------------------------------------------------------------------------
  it('exits 0 and emits "no baseline yet" when baseline file is missing', () => {
    const current = {
      '/login': { raw: 80_000, gzip: 24_000 },
    };
    const currentPath = writeTmp(TMP, 'current2.json', current);
    const outputPath = join(TMP, 'report2.md');
    const missingPath = join(TMP, 'does-not-exist.json');

    // Must NOT throw (exit 0)
    const { code, stdout } = run([
      '--current', currentPath,
      '--baseline', missingPath,
      '--output', outputPath,
    ]);

    assert.equal(code, 0, 'Should exit 0 when baseline is missing');

    const md = readFileSync(outputPath, 'utf8');
    assert.ok(
      md.toLowerCase().includes('no baseline'),
      'Output should contain "no baseline" text'
    );
    assert.ok(
      stdout.toLowerCase().includes('no baseline'),
      'stdout should contain "no baseline" text'
    );
  });

  // -------------------------------------------------------------------------
  // Test 3: new route in current gets 🆕 marker
  // -------------------------------------------------------------------------
  it('marks new routes with 🆕', () => {
    const baseline = {
      '/tree': { raw: 200_000, gzip: 60_000 },
    };
    const current = {
      '/tree': { raw: 200_000, gzip: 60_000 },
      '/research': { raw: 120_000, gzip: 36_000 }, // new
    };

    const baselinePath = writeTmp(TMP, 'baseline3.json', baseline);
    const currentPath = writeTmp(TMP, 'current3.json', current);
    const outputPath = join(TMP, 'report3.md');

    run([
      '--current', currentPath,
      '--baseline', baselinePath,
      '--output', outputPath,
    ]);

    const md = readFileSync(outputPath, 'utf8');
    const researchRow = md.split('\n').find(l => l.includes('/research'));
    assert.ok(researchRow, '/research row should exist');
    assert.ok(researchRow.includes('🆕'), '/research row must have 🆕 (new route)');
  });

  // -------------------------------------------------------------------------
  // Test 4: marker line always appears as the first line
  // -------------------------------------------------------------------------
  it('marker line <!-- ancstra-bundle-report --> is always the first line', () => {
    const baseline = { '/': { raw: 90_000, gzip: 27_000 } };
    const current = { '/': { raw: 90_000, gzip: 27_000 } };

    const baselinePath = writeTmp(TMP, 'baseline4.json', baseline);
    const currentPath = writeTmp(TMP, 'current4.json', current);
    const outputPath = join(TMP, 'report4.md');

    run([
      '--current', currentPath,
      '--baseline', baselinePath,
      '--output', outputPath,
    ]);

    const md = readFileSync(outputPath, 'utf8');
    const firstLine = md.split('\n')[0];
    assert.equal(
      firstLine,
      '<!-- ancstra-bundle-report -->',
      'First line must be the marker comment'
    );
  });
});
